        = 
    callWithHandle {
    uniffiRustCallWithError(OctaPassException) { _status ->
    UniffiLib.uniffi_octapass_ffi_fn_method_octapassserver_change_master_password(
        it,
        
        FfiConverterString.lower(`accessToken`),
        FfiConverterTypeSession.lower(`session`),
        FfiConverterString.lower(`currentPassword`),
        FfiConverterString.lower(`newPassword`),
        FfiConverterString.lower(`secretKey`),_status)
