     * a network error, call it again.
     */
    fun `finish`(`verificationCode`: kotlin.String, `device`: DeviceInfo): SignedIn
    
    /**
     * For the Recovery Kit only. Never store it.
     */
    fun `recoveryCode`(): kotlin.String
    
    /**
     * `OP1-…`: for the Recovery Kit, and to keep on this device (Keychain / Keystore).
     */
    fun `secretKey`(): kotlin.String
    
    companion object
}

