    class InvalidTotp(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    class InvalidGeneratorOptions(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    class InvalidItem(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    class ItemNotFound(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    /**
     * The vault is read-only for this account, or there is no vault to save into.
     */
    class ReadOnlyVault(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    class InvalidUrl(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    /**
     * The WebAuthn request is malformed (a `TypeError` for the relying party).
     */
    class PasskeyInvalidRequest(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    /**
