        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The native `HttpClient` got no response (offline, TLS failure, timeout).
     */
    class Network(
        
        val `reason`: kotlin.String
        ) : OctaPassException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The server answered something that isn't the sync API.
     */
    class InvalidResponse(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    /**
     * The access token expired or was revoked: refresh it, or sign in again.
     */
    class Unauthorized(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    /**
     * The account was deleted on another device. Wipe this account's local data.
     */
    class AccountDeleted(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    class AccountExists(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    class InvalidVerificationCode(
        ) : OctaPassException() {
        override val message
            get() = ""
    }
    
    /**
     * Any other `application/problem+json` answer. Match on `problem_type`, never on the text.
     */
    class Server(
        
        val `status`: kotlin.UShort, 
        
        val `problemType`: kotlin.String, 
        
        val `detail`: kotlin.String?
        ) : OctaPassException() {
        override val message
            get() = "status=${ `status` }, problemType=${ `problemType` }, detail=${ `detail` }"
    }
    
    /**
     * Any other core failure, by its stable code (`malformed_ciphertext`, `key_mismatch` …).
     * (Fields aren't called `message`: Kotlin exceptions already have one.)
     */
    class Core(
        
        val `code`: kotlin.String, 
        
        val `reason`: kotlin.String
        ) : OctaPassException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<OctaPassException> {
        override fun lift(error_buf: RustBuffer.ByValue): OctaPassException = FfiConverterTypeOctaPassError.lift(error_buf)
    }

    
}

/**
