public object FfiConverterTypeOctaPassError : FfiConverterRustBuffer<OctaPassException> {
    override fun read(buf: ByteBuffer): OctaPassException {
        

        return when(buf.getInt()) {
            1 -> OctaPassException.LoginFailed()
            2 -> OctaPassException.InvalidSecretKey()
            3 -> OctaPassException.InvalidRecoveryCode()
            4 -> OctaPassException.UnsupportedKdf()
            5 -> OctaPassException.DeviceUnlockFailed()
            6 -> OctaPassException.PasswordRequired()
            7 -> OctaPassException.Locked()
            8 -> OctaPassException.InvalidTotp()
            9 -> OctaPassException.InvalidGeneratorOptions()
            10 -> OctaPassException.InvalidItem()
            11 -> OctaPassException.ItemNotFound()
            12 -> OctaPassException.ReadOnlyVault()
            13 -> OctaPassException.InvalidUrl()
            14 -> OctaPassException.PasskeyInvalidRequest()
            15 -> OctaPassException.PasskeyRpMismatch()
            16 -> OctaPassException.PasskeyFrameNotAllowed()
            17 -> OctaPassException.PasskeyUnsupportedAlgorithm()
            18 -> OctaPassException.PasskeyExcluded()
            19 -> OctaPassException.PasskeyNotFound()
            20 -> OctaPassException.FlowFinished()
            21 -> OctaPassException.InvalidStore()
            22 -> OctaPassException.Io(
                FfiConverterString.read(buf),
                )
            23 -> OctaPassException.Network(
                FfiConverterString.read(buf),
                )
            24 -> OctaPassException.InvalidResponse()
            25 -> OctaPassException.Unauthorized()
            26 -> OctaPassException.AccountDeleted()
            27 -> OctaPassException.AccountExists()
            28 -> OctaPassException.InvalidVerificationCode()
            29 -> OctaPassException.Server(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            30 -> OctaPassException.Core(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

