            is OctaPassException.PasskeyRpMismatch -> {
                buf.putInt(15)
                Unit
            }
            is OctaPassException.PasskeyFrameNotAllowed -> {
                buf.putInt(16)
                Unit
            }
            is OctaPassException.PasskeyUnsupportedAlgorithm -> {
                buf.putInt(17)
                Unit
            }
            is OctaPassException.PasskeyExcluded -> {
                buf.putInt(18)
                Unit
            }
            is OctaPassException.PasskeyNotFound -> {
                buf.putInt(19)
                Unit
            }
            is OctaPassException.FlowFinished -> {
                buf.putInt(20)
                Unit
            }
            is OctaPassException.InvalidStore -> {
                buf.putInt(21)
                Unit
            }
            is OctaPassException.Io -> {
                buf.putInt(22)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is OctaPassException.Network -> {
                buf.putInt(23)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is OctaPassException.InvalidResponse -> {
                buf.putInt(24)
                Unit
            }
            is OctaPassException.Unauthorized -> {
                buf.putInt(25)
                Unit
            }
            is OctaPassException.AccountDeleted -> {
                buf.putInt(26)
                Unit
            }
            is OctaPassException.AccountExists -> {
                buf.putInt(27)
                Unit
            }
            is OctaPassException.InvalidVerificationCode -> {
                buf.putInt(28)
                Unit
            }
            is OctaPassException.Server -> {
                buf.putInt(29)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`problemType`, buf)
                FfiConverterOptionalString.write(value.`detail`, buf)
                Unit
            }
            is OctaPassException.Core -> {
                buf.putInt(30)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
